'use strict';

// MODULES //

var tape = require( 'tape' );
var linestyle2dasharray = require( '@stdlib/plot/base/linestyle2dasharray' );
var ctor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctor, 'function', 'main export is a function' );
	t.end();
});

tape( 'an instance throws an error if provided an invalid `lineStyle` value', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		'beep',
		5,
		NaN,
		null,
		void 0,
		true,
		false,
		{},
		[ 5 ],
		[ 'beep' ],
		[ '-', 'beep' ],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var chart = ctor();
			chart.lineStyle = value;
		};
	}
});

tape( 'an instance supports setting and getting the property value', function test( t ) {
	var chart;

	chart = ctor({
		'lineStyle': [ '-', '--' ]
	});
	t.deepEqual( chart.lineStyle, [ '-', '--' ], 'returns expected value' );

	chart.lineStyle = [ '-.', ':' ];
	t.deepEqual( chart.lineStyle, [ '-.', ':' ], 'returns expected value' );

	t.end();
});

tape( 'an instance coerces a string value to an array containing a single value', function test( t ) {
	var chart;

	chart = ctor({
		'lineStyle': '--'
	});
	t.deepEqual( chart.lineStyle, [ '--' ], 'returns expected value' );

	chart.lineStyle = ':';
	t.deepEqual( chart.lineStyle, [ ':' ], 'returns expected value' );

	t.end();
});

tape( 'an instance performs a defensive copy of a provided array', function test( t ) {
	var chart;
	var arr;

	arr = [ '-', '--' ];
	chart = ctor({
		'lineStyle': arr
	});
	t.notEqual( chart.lineStyle, arr, 'returns a copy' );
	t.deepEqual( chart.lineStyle, arr, 'returns expected value' );

	arr.push( ':' );
	t.deepEqual( chart.lineStyle, [ '-', '--' ], 'returns expected value' );

	t.end();
});

tape( 'setting the property updates the line style scale range (as dash arrays)', function test( t ) {
	var expected;
	var chart;

	chart = ctor();

	chart.lineStyle = [ '-', '--' ];
	expected = [
		linestyle2dasharray( '-' ),
		linestyle2dasharray( '--' )
	];
	t.deepEqual( chart.lineStyleScale.range, expected, 'returns expected value' );

	chart.lineStyle = ':';
	expected = [
		linestyle2dasharray( ':' )
	];
	t.deepEqual( chart.lineStyleScale.range, expected, 'returns expected value' );

	t.end();
});

tape( 'setting the `lineStyle` property to a new value triggers a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineStyle': [ '-' ]
	});

	chart.on( 'change', onChange );
	chart.lineStyle = [ '--' ];

	function onChange() {
		t.ok( true, 'triggers event' );
		t.end();
	}
});

tape( 'setting the `lineStyle` property to its current value does not trigger a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineStyle': [ '--' ]
	});

	chart.on( 'change', onChange );
	chart.lineStyle = [ '--' ];
	chart.lineStyle = '--';

	t.ok( true, 'does not trigger event' );
	t.end();

	function onChange() {
		t.ok( false, 'should not trigger event' );
	}
});
